INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 4, 'theory', 'Quiz: functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 0, 'What happens if you only define a function, def hello(): print("Hello"), and write nothing else?', '["“Hello” is printed once", "Nothing is printed: a definition does not run the body", "Python raises an error", "“Hello” is printed twice"]', 1, 'A definition only remembers the code under a name; the body runs on the call hello().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 1, 'def f(x): print(x * 2). What is r after r = f(4)?', '["8", "None", "4", "An error"]', 1, 'The function printed 8 but returned nothing: without return, the result is None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 2, 'The call square(5). What is the value 5 called?', '["A parameter", "An argument", "A result", "A key"]', 1, 'A parameter is a name in the function definition, an argument is the actual value at the call.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 3, 'def power(x, n=2): return x ** n. What does power(3) return?', '["6", "9", "27", "An error: an argument is missing"]', 1, 'n was not passed, so the default value 2 is used: 3 ** 2 = 9.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 4, 'What happens on print(local), if the variable local was created only inside a function?', '["Its value is printed", "None is printed", "NameError: the name is unknown outside", "Python creates the variable itself"]', 2, 'Local variables live only inside the function; when it finishes, they disappear.');
